import {mixedParts,flattenParts} from './hybrid-core.js?v=24';
import {createRouteNavigation} from './route-navigation.js?v=22';
import * as THREE from 'three';
import {routeReport} from './route-info.js?v=40';
import {createNetworkModel,cleanNetwork,normalizeRoute,lengthOf,isSea} from './network-core.js?v=40';
import {createRouter} from './travel-core.js?v=24';
const KEY='silvengard-network-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createRouteEditor({D,world,point,camera,canvas,controls,locate,focus,toast,refresh,changed,beforeOpen,onJourney,beforeDrag,title=b=>b.name,scale=()=>D.settings.distanceScale,economyHTML=()=>''}){
 const model=createNetworkModel(D),router=createRouter(D);try{const saved=localStorage.getItem(KEY);if(saved){const raw=JSON.parse(saved);if(D.networkReview?.version===40){const same=(a,b)=>['name','kind','enabled','majorRoute','points','controls','stops','fromCity','toCity'].every(k=>JSON.stringify(a[k])===JSON.stringify(b[k]));raw.routes=raw.routes.filter(r=>!D.networkReview.priorRoutes.some(p=>p.id===r.id&&same(normalizeRoute(p),normalizeRoute(r))));}model.importData(raw);}}catch(e){toast('Rotas locais não carregadas: '+e.message);}let draft=null,selectedPoint=0,picking=null,editing=false,drag=null,unsaved=false,geometryDirty=false,error='',stateFilter='',kindFilter='',query='',showLocal=false,pace='normal',dayHours=8,shipSpeed=D.settings.shipSpeed??11;
 const panel=document.createElement('aside');panel.id='routeEditor';panel.hidden=true;panel.setAttribute('aria-label','Editor de estradas e rotas marítimas');document.body.append(panel);const overlay=new THREE.Group();world.add(overlay);
 const tour=createRouteNavigation({D,focus,title});
 const $=s=>panel.querySelector(s),stateName=id=>D.states.find(s=>s.i===id)?.name.trim()||'Terras neutras';
 function overview(){
  if(!draft?.points?.length)return '<p class="source">Marque pelo menos dois pontos no mapa ou adicione cidades abaixo para criar o percurso.</p>';
  const r=routeReport(D,draft,{scale:scale(),pace,hours:dayHours,shipSpeed}),n=x=>x.toLocaleString('pt-BR',{maximumFractionDigits:1}),time=h=>`${Math.floor(Math.round(h*60)/60)} h ${Math.round(h*60)%60} min`;
  return `<section class="routeOverview" aria-label="Informações da rota">${tour.html(draft)}<div class="routeStats"><div><strong>${n(r.km)} km</strong><small>EXTENSÃO DO TRAÇADO</small></div><div><strong>${time(r.moving)}</strong><small>TEMPO EM MOVIMENTO</small></div><div><strong>${r.days} dia${r.days===1?'':'s'}</strong><small>COM ${dayHours} H DE VIAGEM/DIA</small></div><div><strong>${r.averageLegHours===null?'—':time(r.averageLegHours)}</strong><small>MÉDIA ENTRE LOCALIDADES</small></div></div><div class="routeEstimateControls">${draft.kind!=='road'?`<label>Ritmo marítimo<select id="inspectSeaPace">${[[6,'Lento · 6 km/h'],[11,'Médio · 11 km/h'],[20,'Rápido · 20 km/h'],['custom','Personalizado']].map(([v,label])=>`<option value="${v}" ${(v==='custom'?![6,11,20].includes(shipSpeed):v===shipSpeed)?'selected':''}>${label}</option>`).join('')}</select></label><label>Velocidade do navio · km/h<input id="inspectShipSpeed" type="number" min="0.1" max="100" step="0.5" value="${shipSpeed}"></label>`:`<label>Ritmo de viagem<select id="inspectPace"><option value="normal" ${pace==='normal'?'selected':''}>Normal · 4,5 km/h</option><option value="fast" ${pace==='fast'?'selected':''}>Rápido · 6 km/h</option><option value="slow" ${pace==='slow'?'selected':''}>Lento · 3 km/h</option></select></label>`}${draft.kind==='mixed'?`<label>Ritmo terrestre<select id="inspectPace"><option value="normal" ${pace==='normal'?'selected':''}>Normal · 4,5 km/h</option><option value="fast" ${pace==='fast'?'selected':''}>Rápido · 6 km/h</option><option value="slow" ${pace==='slow'?'selected':''}>Lento · 3 km/h</option></select></label>`:''}<label>Horas por dia<input id="inspectDayHours" type="number" min="1" max="24" value="${dayHours}"></label></div><button id="recalculateRoute">Recalcular estimativa</button><h3>Localidades do percurso</h3>${r.stops.length?`<table class="routeStopTable"><thead><tr><th>Cidade / porto</th><th>Desde o início</th><th>Trecho anterior</th></tr></thead><tbody>${r.stops.map((stop,i)=>`<tr><td>${esc(title(D.cities.find(b=>b.i===stop.id)))}</td><td>${n(stop.along)} km</td><td>${i?n(stop.legKm)+' km<br>'+time(stop.legHours):'Início da sequência'}</td></tr>`).join('')}</tbody></table>`:'<p class="source">Nenhuma cidade junto a este traçado. Você pode criar rotas por pontos livres.</p>'}<p class="source">${draft.kind==='mixed'?`Terra: ${n(r.roadKm)} km a ${n(r.landSpeed)} km/h · Mar: ${n(r.seaKm)} km a ${n(r.shipSpeed)} km/h. `:''}Distâncias medidas ao longo da rota, na escala de ${n(scale())} km/unidade. Localidades a até ${n(scale()*6)} km do traçado. Estradas e rotas marítimas usam terreno normal; a estimativa considera ${n(r.speed)} km/h e não inclui paradas ou encontros. Use Jornadas para uma simulação detalhada.</p></section>`;
 }
 function dispose(){for(const o of [...overlay.children]){overlay.remove(o);o.geometry?.dispose();o.material?.dispose();}}
 function draw(){dispose();if(!draft||panel.hidden){changed();return;}const points=draft.controls,path=drag===null&&!error&&draft.points.length>1?draft.points:points;if(path.length>1){const mesh=new THREE.Line(new THREE.BufferGeometry().setFromPoints(path.map(p=>point(...p,3))),new THREE.LineBasicMaterial({color:'#ffda84',depthTest:false}));mesh.renderOrder=16;overlay.add(mesh);}if(editing)for(const [i,p]of points.entries()){const mesh=new THREE.Mesh(new THREE.SphereGeometry(i===selectedPoint?2.8:1.8,10,6),new THREE.MeshBasicMaterial({color:i===selectedPoint?'#ffdb87':'#7ed4e2',depthTest:false}));mesh.position.copy(point(...p,4));mesh.renderOrder=17;mesh.userData.control=i;overlay.add(mesh);}changed();}
 function persist(){try{localStorage.setItem(KEY,JSON.stringify(model.exportData()));}catch{toast('Exporte as rotas para guardar suas alterações; armazenamento indisponível.');}}
 function rebuild(){error='';try{if(draft.controls.length<2)throw Error('Adicione pelo menos dois pontos.');if(geometryDirty){draft.points=router.trace(draft.controls,draft.kind);if(draft.kind==='mixed'){draft.parts=mixedParts(D,draft.points);draft.points=flattenParts(draft.parts);}}if(lengthOf(draft.points)<.1)throw Error('Os pontos precisam formar um percurso.');}catch(e){error=e.message;}draw();}
 function changedDraft(){unsaved=true;geometryDirty=true;rebuild();render();}
 function choose(id){if(unsaved)return toast('Salve ou descarte as alterações do traçado atual.');const r=D.routes.find(r=>r.id===id);if(!r)return;draft=structuredClone(r);selectedPoint=0;editing=false;geometryDirty=false;picking=null;error='';draw();render();$('.routeBody').scrollTop=0;focus(...r.points[Math.floor(r.points.length/2)],Math.max(160,Math.min(1100,lengthOf(r.points)*1.1)));}
 function make(kind){if(unsaved)return toast('Salve ou descarte o traçado atual.');draft={id:crypto.randomUUID(),name:kind==='mixed'?'Nova rota híbrida':kind==='sea'?'Nova rota marítima':'Nova estrada',kind,group:kind==='mixed'?'mixed':kind==='sea'?'searoutes':'roads',majorRoute:true,enabled:true,points:[],controls:[],stateIds:[]};unsaved=true;geometryDirty=true;editing=true;picking={action:'append'};selectedPoint=0;error='Adicione pelo menos dois pontos.';draw();render();$('.routeBody').scrollTop=0;}
 function routeStates(r){const states=new Set();for(const p of r.points){const c=router.nearest(p);if(c.h>=20&&c.state)states.add(c.state);}for(const id of [r.fromCity,r.toCity]){const b=D.cities.find(b=>b.i===id);if(b)states.add(b.state);}return [...states];}
 function save(){draft.name=$('#routeNameEdit').value.trim()||draft.name;draft.enabled=$('#routeEnabled').checked;draft.majorRoute=$('#routeMajor').checked;rebuild();if(error)return toast(error);const report=routeReport(D,draft);draft.stopMode='explicit';draft.stops=report.stops.map(p=>p.id);draft.tradeUse=draft.stops.length>=2;draft.fromCity=report.stops[0]?.id??null;draft.toCity=report.stops.at(-1)?.id??null;if(draft.kind==='sea')draft.stops=report.stops.map(p=>p.id);draft.stateIds=routeStates(draft);model.save(draft);unsaved=false;geometryDirty=false;picking=null;persist();refresh();draw();render();toast('Traçado salvo');}
 function render(){const top=$('.routeBody')?.scrollTop||0,list=D.routes.filter(r=>(showLocal||r.majorRoute!==false)&&(!stateFilter||r.stateIds?.includes(+stateFilter))&&(!kindFilter||r.kind===kindFilter)&&(!query||(r.name+' '+routeReport(D,r).stops.map(p=>p.name).join(' ')).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))));panel.innerHTML=`<div class="editorHeading"><div><div class="eyebrow">CAMINHOS POR TERRA E MAR</div><h2>Estradas e rotas</h2></div><button id="closeRoutes" title="Fechar rotas">×</button></div><div class="routeBody"><div class="routeBrowse" ${draft?'hidden':''}><div class="editorActions"><button id="newRoad">+ Estrada</button><button id="newSea">+ Marítima</button><button id="newMixed">+ Híbrida</button></div><label>Estado<select id="routeStateFilter"><option value="">Todos os estados</option>${D.states.filter(s=>s.i).map(s=>`<option value="${s.i}" ${stateFilter===String(s.i)?'selected':''}>${esc(s.name.trim())}</option>`).join('')}</select></label><label>Tipo<select id="routeKindFilter"><option value="">Terrestres e marítimas</option><option value="road" ${kindFilter==='road'?'selected':''}>Estradas e trilhas</option><option value="sea" ${kindFilter==='sea'?'selected':''}>Rotas marítimas</option><option value="mixed" ${kindFilter==='mixed'?'selected':''}>Rotas híbridas</option></select></label><label class="editorSwitch"><input id="showLocalPaths" type="checkbox" ${showLocal?'checked':''}> Incluir caminhos locais sem nome próprio</label><label>Buscar rota<input id="routeSearch" value="${esc(query)}" placeholder="Nome da estrada ou de uma cidade"></label><div class="routeList">${list.map(r=>`<button data-route="${esc(r.id)}" class="${r.id===draft?.id?'active':''}"><strong>${r.majorRoute===false?'·':r.kind==='sea'?'⚓':'↝'} ${esc(r.name)}</strong><small>${r.enabled===false?'Desativada · ':''}${r.stateIds?.map(stateName).map(esc).join(' / ')||'Mar aberto'} · ${(lengthOf(r.points)*D.settings.distanceScale).toLocaleString('pt-BR',{maximumFractionDigits:1})} km</small></button>`).join('')||'<p class="source">Nenhuma rota neste filtro.</p>'}</div><p class="source">${list.length} ${showLocal?'traçados':'rotas principais'}. Os caminhos locais continuam no mapa e facilitam as jornadas, sem receber um nome de grande rota. Nomes sem leitura segura no papel são descritivos e podem ser renomeados.</p></div>${draft?`<section class="routeDraft"><button id="backToRoutes">← Todas as rotas</button><h3>${esc(draft.name)}</h3><div class="routeToolbar"><button id="editRouteMap">${editing?'Concluir pontos':'Editar pontos no mapa'}</button><button id="quickSaveRoute" ${unsaved?'':'disabled'}>Salvar alterações</button></div>${unsaved?'<p class="routeNotice">Alterações ainda não salvas.</p>':''}${picking?`<p class="routeNotice">${picking.action==='move'?'Clique no novo lugar do ponto.':'Clique no mapa para acrescentar um ponto.'} ${draft.kind==='mixed'?'Escolha cidades, terra ou uma rota marítima cadastrada. A passagem entre terra e mar é feita pelos portos.':draft.kind==='sea'?'Escolha água ou um porto.':'Escolha terra.'}<button id="stopRoutePick">Concluir marcação</button></p>`:''}${economyHTML(draft.id)}${overview()}<label>Nome<input id="routeNameEdit" maxlength="150" value="${esc(draft.name)}"></label><p class="source">${draft.kind==='mixed'?'↝⚓ Rota híbrida':draft.kind==='sea'?'⚓ Rota marítima':'↝ Estrada terrestre'} · ${esc(draft.nameSource||'Traçado editável')}</p><label class="editorSwitch"><input id="routeMajor" type="checkbox" ${draft.majorRoute!==false?'checked':''}> Rota principal com nome no mapa</label>${draft.stops?.length?`<p class="source">Escalas: ${draft.stops.map(id=>esc(D.cities.find(b=>b.i===id)?.name||id)).join(' → ')}</p>`:''}<label class="editorSwitch"><input id="routeEnabled" type="checkbox" ${draft.enabled?'checked':''}> Exibir e usar nas jornadas</label><div class="editorActions"><button id="journeyRoute">Usar na jornada</button></div><div class="routePointEditor" ${editing?'':'hidden'}><ol class="routePointList">${draft.controls.map((p,i)=>`<li><button data-route-point="${i}" class="${selectedPoint===i?'active':''}">Ponto ${i+1} · ${p[0].toFixed(1)}, ${p[1].toFixed(1)}</button></li>`).join('')}</ol><div class="editorActions"><button id="moveRoutePoint">Mover ponto</button><button id="insertRoutePoint">Inserir depois</button><button id="removeRoutePoint">Remover</button></div><div class="editorActions"><button id="appendRoutePoint">+ Ponto no mapa</button><button id="pointUp">↑ Reordenar</button><button id="pointDown">↓ Reordenar</button></div><label>Adicionar cidade ou porto<select id="routePort"><option value="">Escolha…</option>${D.cities.filter(b=>b.visible&&!b.excluded&&(draft.kind!=='sea'||b.harbor)).map(b=>`<option value="${b.i}">${esc(b.name)}</option>`).join('')}</select></label><button id="addRoutePort">Adicionar ao traçado</button></div>${error?`<p class="journeyError" role="alert">${esc(error)}</p>`:''}<div class="editorActions"><button id="saveRoute">Salvar traçado</button><button id="discardRoute">Descartar</button></div><button id="deleteRoute">Remover esta rota</button><p class="source">Com a edição ligada, arraste os marcadores coloridos para mover os pontos. O caminho é reconstruído sobre terra ou água, conforme o tipo. Salvar confirma o novo traçado; Descartar recupera o último salvo.</p></section>`:'<p class="source">Selecione um traçado para ver o nome e editar seus pontos.</p>'}<div class="editorActions"><button id="undoNetwork" ${model.canUndo?'':'disabled'}>↶ Desfazer</button><button id="redoNetwork" ${model.canRedo?'':'disabled'}>↷ Refazer</button></div><button id="exportNetwork">Exportar estradas e rotas ↓</button><label class="editorImport">Importar estradas e rotas<input id="importNetwork" type="file" accept="application/json" hidden></label><p class="source">Rotas salvas ficam neste navegador e na exportação completa do atlas. Exporte o JSON para enviar sua rede revisada.</p></div>`;
  tour.bind(panel);$('#closeRoutes').onclick=()=>{panel.hidden=true;editing=false;picking=null;draw();};$('#newRoad').onclick=()=>make('road');$('#newSea').onclick=()=>make('sea');$('#newMixed').onclick=()=>make('mixed');$('#routeStateFilter').onchange=e=>{stateFilter=e.target.value;render();};$('#showLocalPaths').onchange=e=>{showLocal=e.target.checked;render();};$('#routeKindFilter').onchange=e=>{kindFilter=e.target.value;render();};$('#routeSearch').oninput=e=>{const at=e.target.selectionStart;query=e.target.value;render();$('#routeSearch').focus();$('#routeSearch').setSelectionRange(at,at);};panel.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>choose(b.dataset.route));
  $('#undoNetwork').onclick=()=>{if(model.undo()){draft=null;unsaved=false;persist();refresh();draw();render();}};$('#redoNetwork').onclick=()=>{if(model.redo()){draft=null;unsaved=false;persist();refresh();draw();render();}};$('#exportNetwork').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(model.exportData(),null,2)],{type:'application/json'}));a.download='silvengard-estradas-rotas.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);};$('#importNetwork').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error('Arquivo muito grande');const d=JSON.parse(await f.text());importData(d.networkEdits||d);toast('Rotas importadas');}catch(err){toast('Não foi possível importar: '+err.message);}finally{e.target.value='';}};
  if(draft){$('#backToRoutes').onclick=()=>{if(unsaved)return toast('Salve ou descarte as alterações antes de voltar.');draft=null;editing=false;picking=null;draw();render();$('.routeBody').scrollTop=0;};$('#quickSaveRoute').onclick=save;if($('#recalculateRoute'))$('#recalculateRoute').onclick=()=>{if($('#inspectPace'))pace=$('#inspectPace').value;if($('#inspectSeaPace')&&$('#inspectSeaPace').value!=='custom')shipSpeed=+$('#inspectSeaPace').value;else if($('#inspectShipSpeed'))shipSpeed=Math.max(.1,Math.min(100,+$('#inspectShipSpeed').value||11));dayHours=Math.max(1,Math.min(24,+$('#inspectDayHours').value||8));render();};if($('#inspectSeaPace'))$('#inspectSeaPace').oninput=$('#inspectSeaPace').onchange=e=>{if(e.target.value==='custom'){$('#inspectShipSpeed').focus();return;}shipSpeed=+e.target.value;render();};if($('#inspectPace'))$('#inspectPace').onchange=e=>{pace=e.target.value;render();};if($('#inspectShipSpeed'))$('#inspectShipSpeed').oninput=e=>{shipSpeed=Math.max(.1,Math.min(100,+e.target.value||11));$('#inspectSeaPace').value=[6,11,20].includes(shipSpeed)?String(shipSpeed):'custom';};if($('#inspectShipSpeed'))$('#inspectShipSpeed').onchange=e=>{shipSpeed=Math.max(.1,Math.min(100,+e.target.value||11));render();};if($('#inspectDayHours'))$('#inspectDayHours').onchange=e=>{dayHours=Math.max(1,Math.min(24,+e.target.value||8));render();};$('#routeNameEdit').oninput=e=>{draft.name=e.target.value;unsaved=true;$('#quickSaveRoute').disabled=false;};$('#routeEnabled').onchange=e=>{draft.enabled=e.target.checked;unsaved=true;$('#quickSaveRoute').disabled=false;};$('#routeMajor').onchange=e=>{draft.majorRoute=e.target.checked;unsaved=true;$('#quickSaveRoute').disabled=false;};$('#editRouteMap').onclick=()=>{editing=!editing;picking=null;draw();render();};$('#journeyRoute').onclick=()=>{if(unsaved)return toast('Salve o traçado antes de planejar a jornada.');onJourney(draft);};if($('#stopRoutePick'))$('#stopRoutePick').onclick=()=>{picking=null;render();};panel.querySelectorAll('[data-route-point]').forEach(b=>b.onclick=()=>{selectedPoint=+b.dataset.routePoint;editing=true;draw();render();focus(...draft.controls[selectedPoint],180);});$('#moveRoutePoint').onclick=()=>{if(!draft.controls.length)return;editing=true;picking={action:'move',index:selectedPoint};draw();render();};$('#insertRoutePoint').onclick=()=>{editing=true;picking={action:'insert',index:selectedPoint+1};render();};$('#appendRoutePoint').onclick=()=>{editing=true;picking={action:'append'};render();};$('#removeRoutePoint').onclick=()=>{draft.controls.splice(selectedPoint,1);selectedPoint=Math.max(0,selectedPoint-1);changedDraft();};for(const [id,delta]of [['pointUp',-1],['pointDown',1]])$('#'+id).onclick=()=>{const j=selectedPoint+delta;if(j<0||j>=draft.controls.length)return;[draft.controls[j],draft.controls[selectedPoint]]=[draft.controls[selectedPoint],draft.controls[j]];selectedPoint=j;changedDraft();};$('#addRoutePort').onclick=()=>{const b=D.cities.find(b=>b.i===+$('#routePort').value);if(!b)return;draft.controls.push(draft.kind==='sea'?b.harbor.waterPoint:[b.x,b.y]);if(draft.controls.length===1)draft.fromCity=b.i;draft.toCity=b.i;draft.stops=[...new Set([...(draft.stops||[]),b.i])];changedDraft();};$('#saveRoute').onclick=save;$('#discardRoute').onclick=()=>{const old=D.routes.find(r=>r.id===draft.id);draft=old?structuredClone(old):null;unsaved=false;picking=null;error='';draw();render();};$('#deleteRoute').onclick=()=>{model.remove(draft.id);draft=null;unsaved=false;picking=null;persist();refresh();draw();render();toast('Rota removida; use Desfazer para recuperar.');};}$('.routeBody').scrollTop=top;
 }
 function pick(xy,city){if(!draft||!picking)return false;if(draft.kind==='sea'&&city?.harbor)xy=city.harbor.waterPoint;const wet=router.nearest(xy).h<20;if(draft.kind==='mixed'&&wet&&!router.isSeaPoint(xy)){toast('Use um porto ou uma rota marítima cadastrada.');return true;}if(draft.kind!=='mixed'&&wet!==(draft.kind==='sea')){toast(draft.kind==='sea'?'Escolha água ou um porto.':'Escolha um ponto em terra.');return true;}draft.name=$('#routeNameEdit')?.value||draft.name;if(draft.controls.length>=200&&picking.action!=='move')return toast('Limite de 200 pontos.');if(picking.action==='move'){draft.controls[picking.index]=[...xy];selectedPoint=picking.index;picking=null;}else if(picking.action==='insert'){draft.controls.splice(picking.index,0,[...xy]);selectedPoint=picking.index;picking=null;}else{draft.controls.push([...xy]);selectedPoint=draft.controls.length-1;}changedDraft();return true;}
 const projected=new THREE.Vector3();function handle(e){if(panel.hidden||!editing||!draft)return null;let best=14**2,result=null;for(const [i,p]of draft.controls.entries()){projected.copy(point(...p,4));projected.y*=world.scale.y;projected.project(camera);const d=((projected.x*.5+.5)*innerWidth-e.clientX)**2+((-projected.y*.5+.5)*innerHeight-e.clientY)**2;if(projected.z<1&&d<best){best=d;result=i;}}return result;}
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;const i=handle(e);if(i===null)return;e.preventDefault();e.stopImmediatePropagation();beforeDrag();canvas.focus({preventScroll:true});drag=i;selectedPoint=i;controls.enabled=false;canvas.setPointerCapture(e.pointerId);},{capture:true});canvas.addEventListener('pointermove',e=>{if(drag===null)return;e.preventDefault();e.stopImmediatePropagation();const xy=locate(e);if(xy){draft.controls[drag]=xy;unsaved=true;geometryDirty=true;draw();}},{capture:true});const end=e=>{if(drag===null)return;e.preventDefault();e.stopImmediatePropagation();drag=null;controls.enabled=true;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);rebuild();render();};canvas.addEventListener('pointerup',end,{capture:true});canvas.addEventListener('pointercancel',end,{capture:true});addEventListener('blur',()=>{drag=null;controls.enabled=true;});
 function importData(raw){const clean=cleanNetwork(raw,D);model.importData(clean);draft=null;unsaved=false;picking=null;persist();refresh();draw();render();}
 render();return {replaceRoutes(routes){model.replaceAll(routes);draft=null;unsaved=false;picking=null;persist();refresh();draw();render();},open(options={}){beforeOpen();panel.hidden=false;if(options.state!==undefined){stateFilter=String(options.state);kindFilter='';query='';showLocal=false;}render();if(options.id)choose(options.id);},close(){panel.hidden=true;editing=false;picking=null;draw();},isPicking:()=>!panel.hidden&&!!picking,pick,exportData:()=>model.exportData(),importData,get editing(){return !panel.hidden&&editing;},get hasUnsaved(){return unsaved;},get dragging(){return drag!==null;}};
}
